// The thing the fixture project's gate scripts act on. It is intentionally tiny: the Phase 33
// capture is about the factory installed on top of it, not about this file. `--self-test` and
// `--build` both exit 0 so the section-14 gate (lint, typecheck, test, build) is reachable.

export function greet(name) {
  return `hello, ${name}`;
}

const mode = process.argv[2] ?? "";
if (mode === "--self-test") {
  if (greet("grug") !== "hello, grug") {
    console.error("self-test: greet() returned an unexpected value");
    process.exit(1);
  }
  console.log("self-test: 1 case, 0 failures");
} else if (mode === "--build") {
  console.log("build: nothing to compile; the fixture ships as plain ES modules");
}

{
  "name": "grugops-capture-target",
  "version": "0.0.0",
  "private": true,
  "description": "The runnable fixture project the Phase 33 live capture installs grugops onto (D-03). Every gate command the section-14 workflow names exists here and exits 0, so emit-verdict is reachable in the target. Deliberately no TypeScript: tsconfig.json compiles scripts/**/*.ts and a fixture .ts would demand a committed .js twin. The source file is .mjs rather than .js because scripts/freshness.ts treats every committed .js under scripts/ as a build output.",
  "type": "module",
  "scripts": {
    "lint": "node --check src/index.mjs",
    "typecheck": "node --check src/index.mjs",
    "test": "node src/index.mjs --self-test",
    "build": "node src/index.mjs --build"
  }
}
